  "misconception": {
    "pack_id": null,
    "wrong": "Скважины надо расставить равномерно по всей площади залежи, как сетку на карте.",
    "right": "Скважины выгоднее сгущать в своде, где лежат основные запасы, и разреживать у края. Сетка должна освещать объём залежи.",
    "claims": ["c1", "c2"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Карта или разрез залежи с положением свода и контура.", "claims": [], "hypothesis": true},
      {"text": "Оценка того, где лежат основные запасы: по объёму залежи, а не по её площади.", "claims": ["c1", "c2"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "План сетки скважин: много точек в своде и мало у края.", "claims": ["c2"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Правило опирается на предположение об освещении объёма. Если оно неверно, сетка получится другой.", "claims": ["c1"], "hypothesis": false},
      {"text": "Сведения о запасах по скважинам появляются после бурения. До этого сетка опирается на предположения.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Аналогия редактора, не из книги: мониторинг распределённой системы. Датчики ставят плотнее там, где больше нагрузки, а не равномерно по всей сети.",
    "breaks_where": "Датчик можно переставить, а скважину нельзя: бурение необратимо и дорого. Распределение запасов заранее известно только приблизительно."
  },
  "now_nuance": {"text": "Гипотеза редактора: сегодня сетку обычно строят по трёхмерной модели залежи и пересчитывают её после каждой новой скважины."},
  "threshold": {
    "is_threshold": true,
    "why": "Без этого сетка кажется делом карты и площади. Понимание, что скважины ставят под объём запасов, меняет весь план бурения."
  },
